#!/usr/bin/env bash
# Claude Code PreToolUse hook（GitHub MCP 工具）：
#   1. 拒绝创建 PR、Issue、评论和评审：GitHub MCP 服务端会在这些正文末尾自动追加
#      "Generated by Claude Code" 页脚和会话链接，仓库内无法拦截，只能不让 AI 发；
#   2. 其余 GitHub 工具的任何字符串参数里出现 AI 署名标记都拒绝。
# 被拒绝的调用会写入 safegit 审计日志。
set -uo pipefail

input="$(cat)"
tool="$(jq -r '.tool_name // empty' <<<"$input")"
[[ -z "$tool" ]] && exit 0

ROOT="${CLAUDE_PROJECT_DIR:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)}"
# shellcheck source=../../scripts/lib/safegit-policy.sh
source "$ROOT/scripts/lib/safegit-policy.sh"

deny() {
  "$ROOT/scripts/safegit" __log "claude-hook: $1" "$tool" >/dev/null 2>&1 || true
  jq -cn --arg r "$1" \
    '{hookSpecificOutput:{hookEventName:"PreToolUse", permissionDecision:"deny", permissionDecisionReason:$r}}'
  exit 0
}

# 服务端会追加 AI 页脚的写入类工具（与 .claude/settings.json 的 deny 列表一致）
case "${tool##*__}" in
  create_pull_request|issue_write|add_issue_comment|update_issue_comment|\
  add_reply_to_pull_request_comment|add_comment_to_pending_review|pull_request_review_write)
    deny "本仓库禁止 AI 通过 GitHub 工具创建 PR、Issue、评论或评审（服务端会自动追加 AI 署名）。请把标题和正文交给用户，由用户自己在 GitHub 上提交"
    ;;
esac

# 其余工具：检查全部字符串参数
text="$(jq -r '[.tool_input | .. | strings] | join("\n")' <<<"$input")"
hit="$(printf '%s\n' "$text" | grep -Eio -- "$SAFEGIT_FORBIDDEN_MSG_RE" | head -n1)"
if [[ -n "$hit" ]]; then
  deny "参数中含禁止的 AI 标识「$hit」，请删除后再调用"
fi

exit 0
